TRUNCATE legend_voce, legend_category CASCADE;
DO $$ BEGIN ASSERT (SELECT count(*) FROM legend_category) = 10, 'expected 10 categories'; ASSERT (SELECT count(*) FROM legend_voce) = 75, 'expected 75 voci'; END $$;
SELECT 'legend ok' AS status, (SELECT count(*) FROM legend_category) AS categories, (SELECT count(*) FROM legend_voce) AS voci;
